//! The Bergamot directions the model catalog offers (`model-catalog/mt-bergamot.json`, generated by
//! `scripts/runtime-packs/bergamot/gen-catalog.mjs`): language-code mapping, routing (direct or through an English
//! pivot), the `bergamot_pairs` listing and the model files of one direction. Pure: install state comes in through a
//! lookup closure, so everything here is unit-tested without a model store.

use super::super::{MtError, MtErrorKind, MtPair};
use crate::services::model_store::{Catalog, CatalogEntry};
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::path::{Path, PathBuf};

/// Catalog family (and id prefix) of the direction entries.
pub const FAMILY: &str = "mt-bergamot";
/// The pivot language: every Mozilla direction goes to or from English.
pub const PIVOT: &str = "en";

/// One direction of the catalog, e.g. `mt-bergamot/en_ja`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Direction {
    /// Catalog id.
    pub id: String,
    /// Helper model key (`en_ja`, `zh-hant_en`): the id without the family prefix.
    pub key: String,
    /// Lower-case codes as used in ids (`en`, `zh`, `zh-hant`).
    pub source: String,
    pub target: String,
    /// Catalog file paths of the entry (relative to its install folder).
    pub files: Vec<String>,
}

/// Every direction of the catalog, indexed by (source, target).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Directions {
    by_pair: BTreeMap<(String, String), Direction>,
    languages: BTreeSet<String>,
}

/// How to translate one pair.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Route {
    /// Source and target are the same language: nothing to translate.
    Same,
    /// One direction, or two through English (`pivot`).
    Models { legs: Vec<Direction>, pivot: bool },
}

impl Directions {
    /// The `mt-bergamot/*` entries of a catalog. Entries whose id does not parse are skipped (logged).
    pub fn from_catalog(catalog: &Catalog) -> Directions {
        Self::from_entries(catalog.entries.iter())
    }

    pub fn from_entries<'a>(entries: impl IntoIterator<Item = &'a CatalogEntry>) -> Directions {
        let mut out = Directions::default();
        for e in entries {
            if e.family != FAMILY {
                continue;
            }
            match parse_id(&e.id) {
                Some((source, target)) => {
                    out.languages.insert(source.clone());
                    out.languages.insert(target.clone());
                    let key = e.id[FAMILY.len() + 1..].to_string();
                    out.by_pair.insert(
                        (source.clone(), target.clone()),
                        Direction {
                            id: e.id.clone(),
                            key,
                            source,
                            target,
                            files: e.files.iter().map(|f| f.path.clone()).collect(),
                        },
                    );
                }
                None => tracing::warn!(target: super::LOG_TARGET, "ignoring catalog entry {:?}: not an mt-bergamot/<source>_<target> id", e.id),
            }
        }
        out
    }

    #[cfg(test)]
    pub fn len(&self) -> usize {
        self.by_pair.len()
    }

    pub fn get(&self, source: &str, target: &str) -> Option<&Direction> {
        self.by_pair.get(&(source.to_string(), target.to_string()))
    }

    /// Every direction, sorted by source then target.
    #[cfg(test)]
    pub fn iter(&self) -> impl Iterator<Item = &Direction> {
        self.by_pair.values()
    }

    /// Map a canonical BCP-47 code (from `translation/languages.ts`) to the lower-case code of the catalog ids, or
    /// `None` when no direction uses that language.
    pub fn lang(&self, canonical: &str) -> Option<String> {
        let code = normalize_code(canonical)?;
        if self.languages.contains(&code) {
            return Some(code);
        }
        // Region / script subtags the models do not distinguish (`pt-pt` → `pt`, `en-us` → `en`). Chinese never
        // falls back across scripts: `normalize_code` already mapped every Traditional form to `zh-hant`.
        let mut base = code.as_str();
        while let Some((head, _)) = base.rsplit_once('-') {
            base = head;
            if base == "zh" && code.starts_with("zh-hant") {
                return None;
            }
            if self.languages.contains(base) {
                return Some(base.to_string());
            }
        }
        None
    }

    /// Route `source` → `target` (canonical codes; `source` "" = unknown, which Bergamot cannot translate).
    pub fn route(&self, source: &str, target: &str) -> Result<Route, MtError> {
        let t = self
            .lang(target)
            .ok_or_else(|| MtError::unsupported_pair(source, target))?;
        if source.trim().is_empty() {
            return Err(MtError::new(
                MtErrorKind::UnsupportedPair,
                format!("Bergamot needs the source language to translate into {target} (it cannot detect it)"),
            ));
        }
        let s = self
            .lang(source)
            .ok_or_else(|| MtError::unsupported_pair(source, target))?;
        if s == t {
            return Ok(Route::Same);
        }
        if let Some(d) = self.get(&s, &t) {
            return Ok(Route::Models {
                legs: vec![d.clone()],
                pivot: false,
            });
        }
        if s != PIVOT && t != PIVOT {
            if let (Some(a), Some(b)) = (self.get(&s, PIVOT), self.get(PIVOT, &t)) {
                return Ok(Route::Models {
                    legs: vec![a.clone(), b.clone()],
                    pivot: true,
                });
            }
        }
        Err(MtError::unsupported_pair(source, target))
    }

    /// `bergamot_pairs`: every direct direction, plus every English pivot the catalog allows, with install state.
    /// `installed(id)` is called once per catalog id.
    pub fn pairs(&self, mut installed: impl FnMut(&str) -> bool) -> Vec<MtPair> {
        let state: HashMap<&str, bool> = self
            .by_pair
            .values()
            .map(|d| (d.id.as_str(), installed(&d.id)))
            .collect();
        let mut out: Vec<MtPair> = self
            .by_pair
            .values()
            .map(|d| MtPair {
                source: canonical_case(&d.source),
                target: canonical_case(&d.target),
                ids: vec![d.id.clone()],
                installed: state[d.id.as_str()],
                pivot: false,
            })
            .collect();
        let into_en: Vec<&Direction> = self
            .by_pair
            .values()
            .filter(|d| d.target == PIVOT)
            .collect();
        let from_en: Vec<&Direction> = self
            .by_pair
            .values()
            .filter(|d| d.source == PIVOT)
            .collect();
        for a in &into_en {
            for b in &from_en {
                if a.source == b.target || self.get(&a.source, &b.target).is_some() {
                    continue;
                }
                out.push(MtPair {
                    source: canonical_case(&a.source),
                    target: canonical_case(&b.target),
                    ids: vec![a.id.clone(), b.id.clone()],
                    installed: state[a.id.as_str()] && state[b.id.as_str()],
                    pivot: true,
                });
            }
        }
        out.sort_by(|x, y| (&x.source, &x.target).cmp(&(&y.source, &y.target)));
        out
    }
}

/// `mt-bergamot/en_ja` → (`en`, `ja`); `mt-bergamot/zh-hant_en` → (`zh-hant`, `en`).
pub fn parse_id(id: &str) -> Option<(String, String)> {
    let rest = id.strip_prefix(FAMILY)?.strip_prefix('/')?;
    let (s, t) = rest.split_once('_')?;
    let ok = |c: &str| !c.is_empty() && c.starts_with(|ch: char| ch.is_ascii_lowercase()) && c.chars().all(|ch| ch.is_ascii_lowercase() || ch == '-');
    (ok(s) && ok(t) && s != t).then(|| (s.to_string(), t.to_string()))
}

/// Lower-case a canonical code and fold the aliases `translation/languages.ts` would have folded (defensive: the TS
/// side sends canonical codes already). `None` for an empty code.
pub fn normalize_code(code: &str) -> Option<String> {
    let c = code.trim().replace('_', "-").to_ascii_lowercase();
    if c.is_empty() {
        return None;
    }
    let mapped = match c.as_str() {
        "zh-hans" | "zh-cn" | "zh-sg" | "zh-my" | "cmn" | "zh-hans-cn" => "zh",
        "zh-tw" | "zh-hk" | "zh-mo" | "zh-hant-tw" | "zh-hant-hk" => "zh-hant",
        "no" | "nor" => "nb",
        "iw" => "he",
        "in" => "id",
        other => other,
    };
    Some(mapped.to_string())
}

/// Canonical casing of an id code for the TS side (`zh-hant` → `zh-Hant`).
pub fn canonical_case(code: &str) -> String {
    match code.split_once('-') {
        Some((base, sub)) if sub.len() == 4 => {
            let mut s = String::with_capacity(code.len());
            s.push_str(base);
            s.push('-');
            let mut chars = sub.chars();
            if let Some(first) = chars.next() {
                s.push(first.to_ascii_uppercase());
            }
            s.extend(chars);
            s
        }
        Some((base, sub)) if sub.len() == 2 => format!("{base}-{}", sub.to_ascii_uppercase()),
        _ => code.to_string(),
    }
}

/// `en-ja`, or `ja-zh via en` for a pivot (canonical casing): the `model` field of a reply.
pub fn describe(legs: &[Direction]) -> String {
    match legs {
        [one] => format!("{}-{}", canonical_case(&one.source), canonical_case(&one.target)),
        [a, b] => format!(
            "{}-{} via {}",
            canonical_case(&a.source),
            canonical_case(&b.target),
            canonical_case(&a.target)
        ),
        _ => String::new(),
    }
}

/// Integer precision the helper must use for a model file (Firefox's rule: `*.intgemm.alphas.bin` carries
/// precomputed activation scales).
pub fn gemm_precision(model_file: &str) -> Option<&'static str> {
    let name = model_file.rsplit(['/', '\\']).next().unwrap_or(model_file);
    if name.ends_with(".intgemm.alphas.bin") {
        Some("int8shiftAlphaAll")
    } else if name.ends_with(".intgemm8.bin") {
        Some("int8shiftAll")
    } else {
        None
    }
}

/// The files of one installed direction, as the helper's `load` message needs them.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelFiles {
    pub model: PathBuf,
    pub lex: Option<PathBuf>,
    /// `[source, target]` vocabularies (the same file twice for a shared vocabulary).
    pub vocabs: [PathBuf; 2],
    pub gemm: &'static str,
}

/// The role of each catalog file of a direction (paths relative to its install folder).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Roles {
    pub model: String,
    pub lex: Option<String>,
    /// `[source, target]` (the same path twice for a shared vocabulary).
    pub vocabs: [String; 2],
    pub gemm: &'static str,
}

/// Which catalog file is the model, the shortlist and the vocabularies (Mozilla's file naming).
pub fn roles(direction: &Direction) -> Result<Roles, MtError> {
    let file = |pred: &dyn Fn(&str) -> bool| {
        direction
            .files
            .iter()
            .find(|p| pred(p.rsplit('/').next().unwrap_or(p)))
            .cloned()
    };
    let bad = |what: &str| MtError::runtime(format!("{}: the catalog entry has no {what} file", direction.id));
    let model = file(&|n| n.starts_with("model.") && n.ends_with(".bin")).ok_or_else(|| bad("model"))?;
    let gemm = gemm_precision(&model).ok_or_else(|| MtError::runtime(format!("{}: {model} is not an intgemm int8 model", direction.id)))?;
    let lex = file(&|n| n.starts_with("lex.") && n.ends_with(".bin"));
    let vocabs = match file(&|n| n.starts_with("vocab.") && n.ends_with(".spm")) {
        Some(v) => [v.clone(), v],
        None => {
            let src = file(&|n| n.starts_with("srcvocab.") && n.ends_with(".spm")).ok_or_else(|| bad("vocabulary"))?;
            let trg = file(&|n| n.starts_with("trgvocab.") && n.ends_with(".spm")).ok_or_else(|| bad("target vocabulary"))?;
            [src, trg]
        }
    };
    Ok(Roles { model, lex, vocabs, gemm })
}

/// Resolve a direction's files inside its install folder; `not_installed` when one is missing on disk.
pub fn model_files(direction: &Direction, dir: &Path) -> Result<ModelFiles, MtError> {
    let r = roles(direction)?;
    let files = ModelFiles {
        model: dir.join(&r.model),
        lex: r.lex.as_ref().map(|l| dir.join(l)),
        vocabs: [dir.join(&r.vocabs[0]), dir.join(&r.vocabs[1])],
        gemm: r.gemm,
    };
    for p in std::iter::once(&files.model)
        .chain(files.lex.iter())
        .chain(files.vocabs.iter())
    {
        if !p.is_file() {
            return Err(MtError::not_installed(vec![direction.id.clone()]));
        }
    }
    Ok(files)
}
